            + 4 * size_of::<&ResolvedFunction>()
            + 4 * size_of::<&mut ReplayBudget>()
            + size_of::<&mut Option<ByteFailure>>()
            + size_of::<Result<(), ByteFailure>>()
            + ClassifierLedger::current_receiving_controls()
            + 6 * size_of::<Incoming<T>>()
            + 6 * size_of::<Box<T>>()
            + 2 * size_of::<BTreeSet<Box<T>>>()
