// Ordinary frontier stores the actual compact refusal, not a Diagnostic wrapper.
// The complete original gateway above remains independently compiled and unchanged.
// This is its direct payer/authentication body; no old gateway is called and no
// authority, String allocator, positive bootstrap, or allowance is introduced.
impl ReplayBudget {
    pub(in crate::cleanup_plan::replay) fn authenticate_zero_compact_into(
        &mut self,
        function: &ResolvedFunction,
        phase: &str,
        refusal: &mut Option<ByteFailure>,
    ) {
        if refusal.is_some() {
            return;
        }
        match self.payer {
            AllocationPayer::LegacyUnobserved => return,
            AllocationPayer::ActiveBuilder => {
                if self.refusal_spent || crate::bounded_output::active_refused() {
                    *refusal =
                        Some(self.compact_refusal(function, "ordinary builder already failed", ""));
                    return;
                }
                if crate::bounded_output::reserve_active_required(0) {
                    return;
                }
            }
            AllocationPayer::SelectedReservation => {
                if self
                    .physical
                    .as_deref_mut()
                    .expect("selected reservation payer")
                    .authenticate_zero()
                {
                    return;
                }
            }
            #[cfg(test)]
            AllocationPayer::Oracle(lease) => {
                if self.refusal_spent || lease.refused_zero() {
                    *refusal =
                        Some(self.compact_refusal(function, "ordinary builder already failed", ""));
                    return;
                }
                if lease.authenticate_zero() {
                    return;
                }
            }
        }
        *refusal = Some(self.compact_refusal(
            function,
            "cleanup replay physical reservation exhausted during ",
            phase,
        ));
    }
}

